import pandas as pd

class Solution:
    def count_seniors_and_juniors(self, candidates: pd.DataFrame) -> pd.DataFrame:
        rows = candidates.to_dict('records')
        hired, budget = [], 70000
        for phase in ('Senior', 'Junior'):
            while True:
                best = None
                for r in rows:
                    if r['experience'] == phase and r['salary'] <= budget:
                        if best is None or r['salary'] < best['salary']:
                            best = r
                if best is None:
                    break
                budget -= int(best['salary'])
                hired.append(int(best['employee_id']))
                rows.remove(best)
        return pd.DataFrame({'employee_id': hired})

