import java.util.*;

class Solution {
    static class Candidate { int id; String exp; long salary;
        Candidate(int id, String exp, long salary){this.id=id;this.exp=exp;this.salary=salary;} }

    public List<Integer> countSeniorsAndJuniors(List<Candidate> candidates) {
        boolean[] taken = new boolean[candidates.size()];
        List<Integer> hired = new ArrayList<>();
        long budget = 70000;
        for (String phase : new String[]{"Senior", "Junior"}) {
            while (true) {
                int best = -1;
                for (int i = 0; i < candidates.size(); i++) {
                    Candidate c = candidates.get(i);
                    if (taken[i] || !c.exp.equals(phase) || c.salary > budget) continue;
                    if (best == -1 || c.salary < candidates.get(best).salary) best = i;
                }
                if (best == -1) break;
                budget -= candidates.get(best).salary;
                hired.add(candidates.get(best).id);
                taken[best] = true;
            }
        }
        return hired;
    }
}

