import pandas as pd

class Solution:
    def count_seniors_and_juniors(self, candidates: pd.DataFrame) -> pd.DataFrame:
        budget = 70000
        hired = []
        for phase in ('Senior', 'Junior'):
            grp = candidates[candidates.experience == phase].sort_values('salary')
            for _, row in grp.iterrows():
                if int(row.salary) <= budget:
                    budget -= int(row.salary)
                    hired.append(int(row.employee_id))
        return pd.DataFrame({'employee_id': hired})

