#include <bits/stdc++.h>
using namespace std;

struct Candidate { int id; string exp; long long salary; };

class Solution {
public:
    vector<int> countSeniorsAndJuniors(vector<Candidate>& candidates) {
        vector<Candidate> seniors, juniors;
        for (auto& c : candidates)
            (c.exp == "Senior" ? seniors : juniors).push_back(c);
        auto hire = [&](vector<Candidate>& group, long long& budget, vector<int>& out) {
            sort(group.begin(), group.end(),
                 [](const Candidate& a, const Candidate& b) { return a.salary < b.salary; });
            for (auto& c : group)
                if (c.salary <= budget) { budget -= c.salary; out.push_back(c.id); }
        };
        vector<int> out;
        long long budget = 70000;
        hire(seniors, budget, out);
        hire(juniors, budget, out);
        return out;
    }
};

