import java.util.*;

class Solution {
    static class Candidate { int id; String exp; long salary;
        Candidate(int id, String exp, long salary){this.id=id;this.exp=exp;this.salary=salary;} }

    public List<Integer> countSeniorsAndJuniors(List<Candidate> candidates) {
        List<Candidate> seniors = new ArrayList<>(), juniors = new ArrayList<>();
        for (Candidate c : candidates)
            (c.exp.equals("Senior") ? seniors : juniors).add(c);
        Comparator<Candidate> bySalary = Comparator.comparingLong(c -> c.salary);
        seniors.sort(bySalary);
        juniors.sort(bySalary);
        List<Integer> out = new ArrayList<>();
        long budget = 70000;
        for (List<Candidate> group : Arrays.asList(seniors, juniors))
            for (Candidate c : group)
                if (c.salary <= budget) { budget -= c.salary; out.add(c.id); }
        return out;
    }
}

